// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    uint256 constant T0 = 1_700_000_000;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        vm.warp(T0);
    }

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return IERC1271.isValidSignature.selector;
    }

    function testFuzz_property(bool isCall, uint256 duration, uint256 expiration) public {
        vm.assume(isCall || !isCall); // keep isCall fully fuzzed
        duration = bound(duration, 0, 10_000 days - 1);
        expiration = bound(expiration, T0 + 1, T0 + 3650 days);

        MockToken token = new MockToken();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: isCall,
            isLong: false,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory signature = new bytes(0);

        c.fillOrder(order, signature, floorAssetTokenIds);

        // Rule: filling a SHORT order must leave positionExpirations[shortOrderHash] == 0;
        // the expiration lives only under the opposite (long) position id.
        assertTrue(c.positionExpirations(uint256(c.hashOrder(order))) == 0);
    }
}

contract MockToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
